#!/usr/bin/env bash
# File-size guard for hand-written Rust sources.
#
# Threshold: 1000 lines. Files of 300-800 lines are the healthy band; 1000 is
# the soft ceiling where a file stops fitting in one review sitting. The limit
# sits above the band so the guard only fires on genuine outliers.
#
# A generated file declares itself in its first five lines:
#
#     //! @generated by `xtask screens`; do not edit.
#
# Any other file above the limit needs an entry in scripts/file-size-allow.txt
# naming the card that will split it. An entry that is no longer needed (the
# file is gone, back under the limit, or now marked @generated) fails the check
# so the list cannot rot.
set -euo pipefail
cd "$(dirname "$0")/.."

limit=1000
allow=scripts/file-size-allow.txt

declare -A allowed=()
if [[ -f $allow ]]; then
    while read -r path recorded _; do
        [[ -z "${path:-}" || $path == \#* ]] && continue
        allowed["$path"]="$recorded"
    done <"$allow"
fi

fail=0
for file in $(find crates xtask -name '*.rs' -type f | sort); do
    head -n 5 "$file" | grep -q '@generated' && continue
    lines=$(wc -l <"$file")
    if ((lines <= limit)); then
        if [[ -n "${allowed[$file]:-}" ]]; then
            echo "file-size: stale exception: $file is $lines lines (recorded ${allowed[$file]}, limit $limit)" >&2
            echo "  remove it from $allow" >&2
            unset 'allowed[$file]'
            fail=1
        fi
        continue
    fi
    if [[ -n "${allowed[$file]:-}" ]]; then
        unset 'allowed[$file]'
        continue
    fi
    echo "file-size: $file has $lines lines (limit $limit)" >&2
    echo "  generated file: put '@generated' in its first five lines" >&2
    echo "  hand-written: split it, or add '$file $lines <split card>' to $allow" >&2
    fail=1
done

for path in "${!allowed[@]}"; do
    if [[ ! -f $path ]]; then
        echo "file-size: stale exception: $path does not exist; remove it from $allow" >&2
    else
        echo "file-size: stale exception: $path is marked @generated; remove it from $allow" >&2
    fi
    fail=1
done

if ((fail == 0)); then
    echo "file-size: ok (limit $limit lines)"
fi
exit "$fail"
